    return 0;
}

#include <stdio.h>

int factorial(int n) {
    if (n == 0) return 1;
    return n * factorial(n - 1);
}
int main(void) {
    printf("%d\n", factorial(5));
    return 0;
}

#include <stdio.h>


int main(void) {
    int stack[3];
    int count = 0;
    stack[count++] = 10;
    stack[count++] = 20;
    while (count > 0) printf("%d\n", stack[--count]);
    return 0;
}

